<script setup>
// Handler SKeyPreviewCard.qml; all requests and navigation stay with the host screen.
import { computed, ref } from 'vue'
import AppButton from '../../controls/AppButton.vue'
import AppMenu from '../../controls/AppMenu.vue'
import AppIcon from '../../controls/AppIcon.vue'
import BusyIndicator from '../../controls/BusyIndicator.vue'
import ItemPreview from '../../controls/ItemPreview.vue'
import ItemSurface from '../../controls/ItemSurface.vue'
import AttachmentCard from '../../controls/AttachmentCard.vue'
import ResponsiveFlow from '../../controls/ResponsiveFlow.vue'
import SnapshotSummary from './SnapshotSummary.vue'
import { contextActions as vContextActions } from '../../controls/contextActions.js'
import { timestampLabel } from '../activity/activity.js'
import { messageDate } from '../messages/messages.js'
import { browserLink } from '../workspace/links.js'
import { t } from '../../i18n.js'
const props = defineProps({ preview: Object, previews: Object, compact: Boolean, now: Number })
const emit = defineEmits(['open', 'retry', 'copy'])
const menu = ref(null), timeHovered = ref(false)
const failed = computed(() => props.preview.status === 'error')
const ready = computed(() => props.preview.status === 'ready')
const canOpen = computed(() => ready.value && (props.preview.kind !== 'message' || props.preview.canOpen))
const icon = computed(() => ({ sobject: 'inventory-2', task: 'task', snapshot: 'snapshot', file: 'description', note: 'notes', message: 'chat', user: 'user', project: 'folder', knowledge: props.preview.articleKind === 'section' ? 'folder-open' : 'book-open' }[props.preview.kind] || 'link'))
const time = computed(() => { const date = messageDate(props.preview.timestamp); return Number.isNaN(date.getTime()) ? '' : timestampLabel(date.toISOString(), props.now ? new Date(props.now) : undefined) })
const rich = computed(() => ready.value && ['note', 'message'].includes(props.preview.kind) && !props.compact)
function activate() { if (failed.value) emit('retry', props.preview.searchKey); else if (canOpen.value) emit('open', props.preview.searchKey) }
function click(event) { if (!event.target.closest('button,a,details') && !window.getSelection()?.toString()) activate() }
</script>
<template>
  <component :is="compact ? ItemSurface : 'article'" v-context-actions="event => menu.openAt(event)" class="skey-preview-card" :class="[preview.kind, { failed, compact, rich }]" :data-skey="preview.searchKey" :aria-busy="preview.status === 'loading'" :role="!rich ? 'link' : undefined" :tabindex="!rich ? 0 : undefined" :aria-label="preview.title || t('TACTIC item')" @click.stop="click" @keydown.enter.self.prevent="activate" @keydown.space.self.prevent="activate">
    <template v-if="rich">
      <div class="skey-author-row"><ItemPreview :source="preview.avatarUrl" :fallback-text="preview.initials" fallback-icon="user" :preview-size="32" :accent="preview.authorColor" round outlined /><div class="skey-message-text">
        <div class="skey-author-heading"><AppButton class="skey-author-name" :style="{ color: preview.authorColor || 'var(--primary)' }" :href="browserLink('skey://sthpw/login?code=' + encodeURIComponent(preview.author))" @click.prevent="emit('open', 'skey://sthpw/login?code=' + encodeURIComponent(preview.author))">{{ preview.authorDisplay || preview.author || t('Removed user') }}</AppButton><time :title="preview.timestamp" @mouseenter="timeHovered = true" @mouseleave="timeHovered = false">{{ timeHovered ? preview.timestamp : time }}</time></div>
        <p v-if="preview.kind === 'message'" class="skey-preview-body">{{ preview.body }}</p>
      </div></div>
      <p v-if="preview.kind === 'note' && preview.body" class="skey-preview-body">{{ preview.body }}</p>
      <SKeyPreviewCard v-for="nested in preview.nestedPreviews || []" :key="nested.searchKey" :preview="previews?.[nested.searchKey] || nested" :previews="previews" :now="now" compact @open="emit('open', $event)" @retry="emit('retry', $event)" @copy="emit('copy', $event)" />
      <small v-if="preview.nestedPreviewCount > (preview.nestedPreviews || []).length">{{ t('+{count} more linked items', { count: preview.nestedPreviewCount - preview.nestedPreviews.length }) }}</small>
      <ResponsiveFlow v-if="preview.attachments?.length" :minimum-cell-width="210" :maximum-columns="2"><AttachmentCard v-for="file in preview.attachments" :key="file.searchKey + file.title" :title="file.title" :extension="file.extension" :size-text="file.size" :preview-url="file.previewUrl" local @activated="emit('open', file.searchKey)" /></ResponsiveFlow>
      <small v-if="preview.attachmentCount > (preview.attachments || []).length">{{ t('+{count} more attachments', { count: preview.attachmentCount - preview.attachments.length }) }}</small>
    </template>
    <template v-else>
      <AppIcon v-if="compact" :name="icon" />
      <ItemPreview v-else :source="preview.previewUrl" :fallback-icon="preview.kind === 'snapshot' ? 'file' : icon" :preview-size="preview.kind === 'snapshot' ? 58 : 48" :accent="'var(--skey-accent)'" :outlined="preview.kind !== 'snapshot'" />
      <SnapshotSummary v-if="preview.kind === 'snapshot' && ready && !compact" :snapshot="preview" />
      <div v-else-if="preview.kind === 'knowledge' && !compact" class="skey-preview-text skey-knowledge-text"><div><small class="skey-kind">{{ t('Knowledge Base') }}</small><small class="skey-article-kind">{{ t(preview.articleKind === 'section' ? 'Section' : 'Article') }}</small></div><strong :title="preview.title">{{ !ready && !failed ? t('Loading article') : preview.title || t('Knowledge Base article') }}</strong><small v-if="failed || !ready || preview.description || preview.excerpt">{{ failed ? t(preview.error || 'Link preview is unavailable') : !ready ? t('Resolving Knowledge Base link') : preview.description || preview.excerpt }}</small></div>
      <div v-else class="skey-preview-text"><div><small v-if="!compact" class="skey-kind">{{ t(preview.kind === 'knowledge' ? 'Knowledge Base' : preview.kind === 'sobject' ? 'SObject' : preview.kind === 'user' ? 'User' : preview.kind === 'project' ? 'Project' : preview.kind === 'task' ? 'Task' : preview.kind === 'file' ? 'File' : preview.kind === 'note' ? 'Note' : preview.kind === 'message' ? 'Message' : 'Snapshot') }}</small><strong :title="preview.title">{{ preview.kind === 'knowledge' && !ready && !failed ? t('Loading article') : preview.title || t('TACTIC item') }}</strong><small v-if="preview.kind === 'knowledge'" class="skey-article-kind">{{ t(preview.articleKind === 'section' ? 'Section' : 'Article') }}</small></div><span v-if="!compact && preview.subtitle && preview.kind !== 'knowledge'">{{ preview.subtitle }}</span><small>{{ failed ? t(preview.error || 'Link preview is unavailable') : !ready ? t('Resolving link') : preview.kind === 'knowledge' ? preview.description || preview.excerpt : preview.detail || (compact ? preview.subtitle : '') }}</small></div>
      <BusyIndicator v-if="!ready && !failed" running />
      <AppButton v-else-if="!compact" class="skey-open" :icon="failed ? 'refresh' : preview.kind === 'knowledge' ? 'MDI_ARROW_RIGHT' : 'MDI_OPEN_IN_NEW'" icon-only :label="failed ? 'Retry preview' : preview.kind === 'snapshot' ? 'Open snapshot' : preview.kind === 'knowledge' ? 'Open article' : 'Open linked item'" @click="activate" />
    </template>
    <AppMenu ref="menu" class="skey-actions" label="Link actions" overlay>
      <AppButton v-if="failed" label="Retry preview" icon="refresh" @click="emit('retry', preview.searchKey)" />
      <AppButton v-else :label="preview.kind === 'message' && !canOpen ? 'Source conversation is unavailable' : 'Open linked item'" icon="MDI_OPEN_IN_NEW" :disabled="!canOpen" @click="emit('open', preview.searchKey)" />
      <AppButton label="Copy sKey" icon="link" @click="emit('copy', preview.searchKey)" />
    </AppMenu>
  </component>
</template>
<style>
.skey-preview-card { --skey-accent:var(--primary); position:relative; width:100%; min-width:0; height:72px; display:flex; align-items:center; gap:10px; padding:9px 6px 9px 9px; background:var(--surface-container); border:1px solid var(--outline-variant); border-radius:14px; cursor:pointer; transition:background-color var(--motion-hover); }.skey-preview-card:hover { background:var(--surface-high); }.skey-preview-card.failed { border-color:var(--error); }.skey-preview-card.failed .skey-preview-text > small { color:var(--error); }.skey-preview-card.task { --skey-accent:var(--success); }.skey-preview-card.snapshot { --skey-accent:var(--violet); height:88px; }.skey-preview-card.file, .skey-preview-card.project { --skey-accent:var(--cyan); }.skey-preview-card.note { --skey-accent:var(--yellow); }.skey-preview-card.user, .skey-preview-card.knowledge { --skey-accent:var(--tertiary); }.skey-preview-card.snapshot::before, .skey-preview-card.knowledge::before { content:''; position:absolute; left:-1px; width:3px; top:7px; bottom:7px; border-radius:2px; background:var(--skey-accent); }.skey-preview-card > .image-picker-preview { flex:none; width:48px; height:48px; border-radius:4px; color:var(--on-selected); }.skey-preview-card.snapshot > .image-picker-preview { width:58px; height:58px; border-radius:9px; background:color-mix(in srgb, var(--skey-accent) 60.606%, black); color:var(--on-selected); }.skey-preview-card.knowledge { height:auto; min-height:72px; gap:11px; }.skey-preview-card.knowledge > .image-picker-preview { width:46px; height:46px; background:color-mix(in srgb, var(--tertiary) 85%, var(--surface-container)); }.skey-preview-card.knowledge > .image-picker-preview .app-icon { font-size:19px; }.skey-preview-text { display:flex; flex:1; min-width:0; flex-direction:column; gap:2px; }.skey-preview-text > div { display:flex; align-items:center; min-width:0; gap:6px; }.skey-preview-text strong { font-size:var(--text-body-large); font-weight:600; }.skey-preview-text strong, .skey-preview-text > span, .skey-preview-text > small { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }.skey-preview-text > span { font-size:var(--text-label); color:var(--muted); }.skey-preview-text small { font-size:var(--text-caption); color:var(--muted); }.skey-preview-text .skey-kind { color:var(--skey-accent); font-weight:700; text-transform:uppercase; flex:none; }.skey-article-kind { padding:2px 5px; border-radius:10px; background:var(--surface-high); }.skey-preview-card > .busy-indicator { width:28px; height:28px; flex:0 0 28px; }.skey-open.app-button { flex:none; min-width:28px; min-height:28px; width:28px; height:28px; padding:0; color:var(--primary); background:transparent; border:0; }.skey-preview-card > .skey-actions { position:absolute; top:3px; right:3px; opacity:0; }.skey-preview-card:hover > .skey-actions, .skey-preview-card:focus-within > .skey-actions, .skey-preview-card > .skey-actions[open] { opacity:1; }.skey-actions > summary { min-width:24px; min-height:24px; width:24px; height:24px; background:var(--surface-high); }.skey-preview-card.rich { height:auto; min-height:0; padding:9px 11px; display:flex; align-items:stretch; flex-direction:column; gap:8px; cursor:default; }.skey-preview-card.message.rich { background:var(--surface-high); }.skey-author-row { display:flex; gap:8px; align-items:flex-start; }.skey-author-row > .image-picker-preview { width:32px; height:32px; flex:none; }.skey-message-text { flex:1; min-width:0; }.skey-author-heading { display:flex; align-items:center; gap:6px; padding-right:24px; }.skey-author-name.app-button { padding:0; min-height:0; border:0; background:transparent; font-size:var(--text-label); font-weight:600; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }.skey-author-name:hover { text-decoration:underline; }.skey-author-heading time { margin-left:auto; flex:none; font-size:var(--text-caption); color:var(--muted); }.skey-preview-body { margin:7px 0 0; font-size:14px; white-space:pre-wrap; overflow-wrap:anywhere; font-weight:400; user-select:text; line-height:normal; }.skey-preview-card.note .skey-preview-body { margin:0; }.skey-preview-card.rich > small { color:var(--muted); font-size:var(--text-caption); }.skey-preview-card.compact { height:48px; padding:0 9px; border-radius:10px; gap:8px; background:var(--item-interaction); border:1px solid transparent; }.skey-preview-card.compact > .app-icon { flex:none; font-size:17px; color:var(--primary); }.skey-preview-card.compact:hover { background:var(--item-interaction); }.skey-preview-card.compact::before { display:none; }.skey-preview-card.compact.failed { border-color:transparent; }.skey-preview-card.compact.failed > .app-icon { color:var(--error); }.skey-preview-card.compact .skey-preview-text strong { font-size:var(--text-label); }.skey-preview-card.compact .skey-preview-text > div { padding-right:20px; }@media(pointer:coarse) { .skey-preview-card > .skey-actions { opacity:1; } }
.skey-knowledge-text { gap:3px; }.skey-knowledge-text .skey-kind { text-transform:none; }.skey-knowledge-text .skey-article-kind { height:20px; display:inline-flex; align-items:center; padding:0 5px; }.skey-preview-card.knowledge > .image-picker-preview { align-self:flex-start; border-radius:var(--item-radius); }.skey-preview-card.knowledge > .image-picker-preview .app-icon, .skey-preview-card.knowledge .skey-open { color:var(--tertiary); }.skey-preview-card.knowledge { min-height:0; padding:9px; }.skey-knowledge-text > strong { line-height:18px; }.skey-knowledge-text > small { line-height:14px; }.skey-preview-card.failed .skey-open { color:var(--error); }
.skey-open .app-icon { width:17px; height:17px; font-size:17px; }
</style>
